// ChatsServiceHandler is an implementation of the app.v1.ChatsService service.
type ChatsServiceHandler interface {
	// Returns the existing private chat with the user when there is one.
	CreatePrivate(context.Context, *connect.Request[v1.CreatePrivateRequest]) (*connect.Response[v1.CreatePrivateResponse], error)
	CreateGroup(context.Context, *connect.Request[v1.CreateGroupRequest]) (*connect.Response[v1.CreateGroupResponse], error)
	CreateChannel(context.Context, *connect.Request[v1.CreateChannelRequest]) (*connect.Response[v1.CreateChannelResponse], error)
	GetDialogs(context.Context, *connect.Request[v1.GetDialogsRequest]) (*connect.Response[v1.GetDialogsResponse], error)
	GetChat(context.Context, *connect.Request[v1.GetChatRequest]) (*connect.Response[v1.GetChatResponse], error)
	// Channels: admins only.
	GetMembers(context.Context, *connect.Request[v1.GetMembersRequest]) (*connect.Response[v1.GetMembersResponse], error)
	// Banned users (see RemoveMember) come back in failed_user_ids unless the
	// caller is an admin; an admin adding them lifts the ban.
	AddMembers(context.Context, *connect.Request[v1.AddMembersRequest]) (*connect.Response[v1.AddMembersResponse], error)
	// Removes a member, by default also banning them (ban unset or true): a
	// banned user cannot rejoin through any invite link, nor be added back by
	// a non-admin, until an admin unbans them, and the invite links they
	// created in the chat are revoked. ban = false only removes.
	RemoveMember(context.Context, *connect.Request[v1.RemoveMemberRequest]) (*connect.Response[v1.RemoveMemberResponse], error)
	// The owner leaving hands ownership to the longest-serving admin. When
	// other members remain but none is an admin, it fails with
	// failed_precondition (message prefix "owner_needs_admin"); only this
	// case returns failed_precondition here.
	LeaveChat(context.Context, *connect.Request[v1.LeaveChatRequest]) (*connect.Response[v1.LeaveChatResponse], error)
	// Lifts a ban (admins). The user is not added back.
	UnbanMember(context.Context, *connect.Request[v1.UnbanMemberRequest]) (*connect.Response[v1.UnbanMemberResponse], error)
	// Users banned from the chat, by user id (admins).
	GetBannedMembers(context.Context, *connect.Request[v1.GetBannedMembersRequest]) (*connect.Response[v1.GetBannedMembersResponse], error)
	// Sets one member's permission bitmask.
	SetMemberPermissions(context.Context, *connect.Request[v1.SetMemberPermissionsRequest]) (*connect.Response[v1.SetMemberPermissionsResponse], error)
	SetAdmin(context.Context, *connect.Request[v1.SetAdminRequest]) (*connect.Response[v1.SetAdminResponse], error)
	// Creates an invite link (>= 128 bits of entropy).
	ExportInviteLink(context.Context, *connect.Request[v1.ExportInviteLinkRequest]) (*connect.Response[v1.ExportInviteLinkResponse], error)
	// Joins after the user confirmed in the client. A link works only while
	// its creator is still a member allowed to invite; a banned user gets
	// permission_denied.
	JoinByInvite(context.Context, *connect.Request[v1.JoinByInviteRequest]) (*connect.Response[v1.JoinByInviteResponse], error)
	SetHistoryVisibility(context.Context, *connect.Request[v1.SetHistoryVisibilityRequest]) (*connect.Response[v1.SetHistoryVisibilityResponse], error)
	UpdateChatInfo(context.Context, *connect.Request[v1.UpdateChatInfoRequest]) (*connect.Response[v1.UpdateChatInfoResponse], error)
	// The caller's dialogs of the given chats (read state, top message), e.g.
	// to refresh a few chats without reloading the whole list.
	GetPeerDialogs(context.Context, *connect.Request[v1.GetPeerDialogsRequest]) (*connect.Response[v1.GetPeerDialogsResponse], error)
	// Previews the chat behind an invite link before the user confirms.
	CheckInvite(context.Context, *connect.Request[v1.CheckInviteRequest]) (*connect.Response[v1.CheckInviteResponse], error)
	GetInviteLinks(context.Context, *connect.Request[v1.GetInviteLinksRequest]) (*connect.Response[v1.GetInviteLinksResponse], error)
	RevokeInviteLink(context.Context, *connect.Request[v1.RevokeInviteLinkRequest]) (*connect.Response[v1.RevokeInviteLinkResponse], error)
	// Forum topics of a group (Chat.forum). A topic is metadata of the group:
	// its messages carry topic_id inside the group's single seq, and sync stays
	// per chat.
	GetForumTopics(context.Context, *connect.Request[v1.GetForumTopicsRequest]) (*connect.Response[v1.GetForumTopicsResponse], error)
	CreateForumTopic(context.Context, *connect.Request[v1.CreateForumTopicRequest]) (*connect.Response[v1.CreateForumTopicResponse], error)
	EditForumTopic(context.Context, *connect.Request[v1.EditForumTopicRequest]) (*connect.Response[v1.EditForumTopicResponse], error)
	// Only admins post in a closed topic.
	CloseForumTopic(context.Context, *connect.Request[v1.CloseForumTopicRequest]) (*connect.Response[v1.CloseForumTopicResponse], error)
	// A hidden topic leaves the topic list; its messages stay readable and
	// searchable by members.
	HideForumTopic(context.Context, *connect.Request[v1.HideForumTopicRequest]) (*connect.Response[v1.HideForumTopicResponse], error)
	// Mutes or unmutes the caller's notifications of a chat (Dialog.mute_until).
	// The caller's other sessions get dialog_mute.
	SetDialogMute(context.Context, *connect.Request[v1.SetDialogMuteRequest]) (*connect.Response[v1.SetDialogMuteResponse], error)
	// Pins a chat on top of the caller's list or unpins it, at most 5 chats;
	// one more fails with failed_precondition
	// (message prefix "pinned_dialogs_limit"). The caller's sessions get
	// pinned_dialogs.
	SetDialogPinned(context.Context, *connect.Request[v1.SetDialogPinnedRequest]) (*connect.Response[v1.SetDialogPinnedResponse], error)
	// Reorders the caller's pinned chats; chat_ids must be exactly the pinned
	// chats.
	ReorderPinnedDialogs(context.Context, *connect.Request[v1.ReorderPinnedDialogsRequest]) (*connect.Response[v1.ReorderPinnedDialogsResponse], error)
	// Groups and channels: the owner deletes the chat for every member (each
	// gets chat_deleted with for_everyone; messages are purged from the server
	// within the hour). Private chats: removes the chat and its history for
	// the caller only; it comes back with the next message.
	DeleteChat(context.Context, *connect.Request[v1.DeleteChatRequest]) (*connect.Response[v1.DeleteChatResponse], error)
	// Groups both the caller and the user are current members of, and
	// channels where the user is a member and the caller an admin (channel
	// members are visible to admins only).
	GetCommonChats(context.Context, *connect.Request[v1.GetCommonChatsRequest]) (*connect.Response[v1.GetCommonChatsResponse], error)
	// Marks a chat as unread for the caller (Dialog.unread_mark) or clears
	// the mark; reading the chat (ReadHistory) clears it too. The caller's
	// sessions get dialog_unread_mark.
	SetDialogUnreadMark(context.Context, *connect.Request[v1.SetDialogUnreadMarkRequest]) (*connect.Response[v1.SetDialogUnreadMarkResponse], error)
	// How many members of a group are online now, counted on the server
	// (approximate: cached briefly, capped). Members whose last-seen privacy
	// hides their status from the caller are not counted. Channels: admins
	// only.
	GetChatOnlineCount(context.Context, *connect.Request[v1.GetChatOnlineCountRequest]) (*connect.Response[v1.GetChatOnlineCountResponse], error)
	// The caller's notification settings (defaults until changed).
	GetNotificationSettings(context.Context, *connect.Request[v1.GetNotificationSettingsRequest]) (*connect.Response[v1.GetNotificationSettingsResponse], error)
	// Changes the given settings; the caller's sessions get
	// notification_settings.
	SetNotificationSettings(context.Context, *connect.Request[v1.SetNotificationSettingsRequest]) (*connect.Response[v1.SetNotificationSettingsResponse], error)
}

